import { Context, Effect, Exit, Layer } from "effect";

import type {
  HealthCheckData,
  HealthCheckOutcome,
  HealthCheckResult,
  HealthDownResponse,
  HealthUpResponse,
} from "./schema";

export type HealthCheck<Requirements = never> = {
  readonly name: string;
  readonly check: Effect.Effect<HealthCheckOutcome, unknown, Requirements>;
};

export type HealthServiceChecks<Requirements = never> = {
  readonly live?: ReadonlyArray<HealthCheck<Requirements>>;
  readonly ready?: ReadonlyArray<HealthCheck<Requirements>>;
  readonly started?: ReadonlyArray<HealthCheck<Requirements>>;
};

export type HealthServiceOptions<Requirements = never> = {
  readonly checks?: HealthServiceChecks<Requirements>;
};

type RegisteredHealthChecks = {
  readonly live: ReadonlyArray<HealthCheck>;
  readonly ready: ReadonlyArray<HealthCheck>;
  readonly started: ReadonlyArray<HealthCheck>;
};

class HealthServiceConfig extends Context.Service<
  HealthServiceConfig,
  RegisteredHealthChecks
>()("@krak-stack/registry/HealthServiceConfig") {
  static readonly layerWith = <Requirements = never>({
    checks = {},
  }: HealthServiceOptions<Requirements> = {}) =>
    Layer.effect(
      this,
      Effect.gen(function* () {
        const services = yield* Effect.context<Requirements>();
        const resolve = (
          registered: ReadonlyArray<HealthCheck<Requirements>> | undefined,
        ): ReadonlyArray<HealthCheck> =>
          (registered ?? []).map(({ name, check }) => ({
            name,
            check: Effect.provide(check, services),
          }));

        return {
          live: resolve(checks.live),
          ready: resolve(checks.ready),
          started: resolve(checks.started),
        };
      }),
    );
}

export class HealthService extends Context.Service<HealthService>()(
  "@krak-stack/registry/HealthService",
  {
    make: Effect.gen(function* () {
      const checks = yield* HealthServiceConfig;
      const allChecks = Array.from(
        new Set([...checks.live, ...checks.ready, ...checks.started]),
      );
      const execute = Effect.fn("HealthService.execute")(function* (
        healthCheck: HealthCheck,
      ) {
        const exit = yield* Effect.exit(healthCheck.check);

        if (!Exit.isSuccess(exit)) {
          return {
            name: healthCheck.name,
            status: "DOWN",
          } satisfies HealthCheckResult;
        }

        return exit.value.data === undefined
          ? {
              name: healthCheck.name,
              status: exit.value.status,
            }
          : {
              name: healthCheck.name,
              status: exit.value.status,
              data: exit.value.data,
            };
      });
      const run = Effect.fn("HealthService.run")(function* (
        registered: ReadonlyArray<HealthCheck>,
      ) {
        const results = yield* Effect.forEach(registered, execute, {
          concurrency: "unbounded",
        });

        if (results.every(({ status }) => status === "UP")) {
          return {
            status: "UP",
            checks: results,
          } satisfies HealthUpResponse;
        }

        return {
          status: "DOWN",
          checks: results,
        } satisfies HealthDownResponse;
      });

      const aggregate = Effect.fn("HealthService.aggregate")(() =>
        run(allChecks),
      );
      const live = Effect.fn("HealthService.live")(() => run(checks.live));
      const ready = Effect.fn("HealthService.ready")(() => run(checks.ready));
      const started = Effect.fn("HealthService.started")(() =>
        run(checks.started),
      );

      return { aggregate, live, ready, started };
    }),
  },
) {
  static readonly up = (data?: HealthCheckData): HealthCheckOutcome =>
    data === undefined ? { status: "UP" } : { status: "UP", data };

  static readonly down = (data?: HealthCheckData): HealthCheckOutcome =>
    data === undefined ? { status: "DOWN" } : { status: "DOWN", data };

  static readonly layer = Layer.effect(this, this.make).pipe(
    Layer.provide(HealthServiceConfig.layerWith()),
  );

  static readonly layerWith = <Requirements = never>(
    options: HealthServiceOptions<Requirements>,
  ) =>
    Layer.effect(this, this.make).pipe(
      Layer.provide(HealthServiceConfig.layerWith(options)),
    );
}

export * from "./api.builder";
export * from "./api.group";
export * from "./schema";

import { Schema } from "effect";
import { HttpApiSchema } from "effect/unstable/httpapi";

export const HealthStatus = Schema.Literals(["UP", "DOWN"]).annotate({
  identifier: "HealthStatus",
  title: "Health Status",
  description: "Whether a health check is up or down",
});
export type HealthStatus = typeof HealthStatus.Type;

export const HealthCheckData = Schema.Record(
  Schema.String,
  Schema.Union([Schema.String, Schema.Boolean, Schema.Number]),
).annotate({
  identifier: "HealthCheckData",
  title: "Health Check Data",
  description: "Non-sensitive diagnostic values for a health check",
});
export type HealthCheckData = typeof HealthCheckData.Type;

export const HealthCheckOutcome = Schema.Struct({
  status: HealthStatus,
  data: Schema.optionalKey(HealthCheckData),
}).annotate({
  identifier: "HealthCheckOutcome",
  title: "Health Check Outcome",
  description: "The status and optional diagnostic data returned by a check",
});
export type HealthCheckOutcome = typeof HealthCheckOutcome.Type;

export const HealthCheckResult = Schema.Struct({
  name: Schema.NonEmptyString,
  status: HealthStatus,
  data: Schema.optionalKey(HealthCheckData),
}).annotate({
  identifier: "HealthCheckResult",
  title: "Health Check Result",
  description: "The outcome of a named health check",
});
export type HealthCheckResult = typeof HealthCheckResult.Type;

export const HealthUpResponse = Schema.Struct({
  status: Schema.Literal("UP"),
  checks: Schema.Array(HealthCheckResult),
}).annotate({
  identifier: "HealthUpResponse",
  title: "Healthy Response",
  description: "A response where all health checks are up",
  examples: [{ status: "UP", checks: [] }],
});
export type HealthUpResponse = typeof HealthUpResponse.Type;

export const HealthDownResponse = Schema.Struct({
  status: Schema.Literal("DOWN"),
  checks: Schema.Array(HealthCheckResult),
})
  .pipe(HttpApiSchema.status(503))
  .annotate({
    identifier: "HealthDownResponse",
    title: "Unhealthy Response",
    description: "A response where one or more health checks are down",
    examples: [
      {
        status: "DOWN",
        checks: [{ name: "database", status: "DOWN" }],
      },
    ],
  });
export type HealthDownResponse = typeof HealthDownResponse.Type;

export const HealthResponse = Schema.Union([
  HealthUpResponse,
  HealthDownResponse,
]).annotate({
  identifier: "HealthResponse",
  title: "Health Response",
  description: "An aggregate health response",
});
export type HealthResponse = typeof HealthResponse.Type;

import {
  HttpApiEndpoint,
  HttpApiError,
  HttpApiGroup,
  OpenApi,
} from "effect/unstable/httpapi";

import { HealthDownResponse, HealthUpResponse } from "./schema";

const errors = [HealthDownResponse, HttpApiError.InternalServerError] as const;

export const HealthApiGroup = HttpApiGroup.make("health")
  .annotateMerge(
    OpenApi.annotations({
      title: "Health",
      description: "Application health checks",
    }),
  )
  .add(
    HttpApiEndpoint.get("getHealth", "/health", {
      success: HealthUpResponse,
      error: errors,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Get aggregate health",
        description:
          "Runs all registered liveness, readiness, and startup checks.",
      }),
    ),
  )
  .add(
    HttpApiEndpoint.get("getLiveness", "/health/live", {
      success: HealthUpResponse,
      error: errors,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Get application liveness",
        description: "Returns whether the application process is responsive.",
      }),
    ),
  )
  .add(
    HttpApiEndpoint.get("getReadiness", "/health/ready", {
      success: HealthUpResponse,
      error: errors,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Get application readiness",
        description:
          "Returns whether the application is ready to serve traffic.",
      }),
    ),
  )
  .add(
    HttpApiEndpoint.get("getStartup", "/health/started", {
      success: HealthUpResponse,
      error: errors,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Get application startup status",
        description: "Returns whether the application has completed startup.",
      }),
    ),
  );

import { Effect } from "effect";
import { HttpRouter } from "effect/unstable/http";
import { HttpApiBuilder, HttpApiGroup } from "effect/unstable/httpapi";

import { HealthApiGroup } from "./api.group";
import { HealthService } from "./index";
import type { HealthResponse } from "./schema";

const respond = (check: Effect.Effect<HealthResponse>) =>
  check.pipe(
    Effect.flatMap((response) =>
      response.status === "UP"
        ? Effect.succeed(response)
        : Effect.fail(response),
    ),
  );

export const healthHandler = <const Prefix extends HttpRouter.PathInput>(
  handlers: HttpApiBuilder.Handlers.FromGroup<
    HttpApiGroup.AddPrefix<typeof HealthApiGroup, Prefix>
  >,
) =>
  handlers
    .handle("getHealth", () =>
      Effect.flatMap(HealthService, ({ aggregate }) => respond(aggregate())),
    )
    .handle("getLiveness", () =>
      Effect.flatMap(HealthService, ({ live }) => respond(live())),
    )
    .handle("getReadiness", () =>
      Effect.flatMap(HealthService, ({ ready }) => respond(ready())),
    )
    .handle("getStartup", () =>
      Effect.flatMap(HealthService, ({ started }) => respond(started())),
    );

